# General knowledge: geography of India and the world, the Constitution and
# polity, and the economy. Static facts only (no current affairs, no
# office-holders, no figures that change yearly). Key written first.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Rivers", "Which river forms much of the border between Uttarakhand and Nepal?",
      ["Kali", "Gandak", "Kosi", "Teesta"],
      "The Kali, also called the Sharda or Mahakali, marks much of the western border of Nepal with Uttarakhand. The Gandak and Kosi flow from Nepal into Bihar, and the Teesta drains Sikkim."),
    S(1, 2, "Plateaus", "The Chota Nagpur Plateau, rich in coal and iron ore, lies mostly in which state?",
      ["Jharkhand", "Odisha", "Chhattisgarh", "Madhya Pradesh"],
      "Most of the Chota Nagpur Plateau is in Jharkhand, with edges in Odisha, Chhattisgarh, West Bengal and Bihar. It holds the Damodar valley coalfields."),
    S(1, 1, "World geography", "The Panama Canal links which two oceans?",
      ["Atlantic and Pacific", "Atlantic and Indian", "Pacific and Indian", "Arctic and Atlantic"],
      "The Panama Canal cuts across the Isthmus of Panama and joins the Atlantic (through the Caribbean Sea) to the Pacific. The Suez Canal links the Mediterranean and the Red Sea."),
    S(1, 2, "Parliament", "Which Article of the Constitution of India defines a Money Bill?",
      ["Article 110", "Article 108", "Article 112", "Article 117"],
      "Article 110 defines a Money Bill. Article 108 covers joint sittings, Article 112 the annual financial statement (the budget) and Article 117 other financial bills."),
    S(1, 2, "Constitution", "The power of judicial review in the Indian Constitution was modelled mainly on the constitution of which country?",
      ["United States", "United Kingdom", "Ireland", "Canada"],
      "Judicial review, the power of courts to strike down laws that break the Constitution, comes from the United States. The parliamentary system came from the United Kingdom."),
    S(1, 2, "Economy", "Which Constitution Amendment Act made way for the Goods and Services Tax?",
      ["101st", "100th", "102nd", "103rd"],
      "The Constitution (One Hundred and First Amendment) Act, 2016 added Article 246A and enabled GST, which began on 1 July 2017."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "States", "Which Indian state shares a land border with the largest number of other states?",
      ["Uttar Pradesh", "Madhya Pradesh", "Assam", "Chhattisgarh"],
      "Uttar Pradesh touches eight states (Uttarakhand, Himachal Pradesh, Haryana, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand and Bihar) and also Delhi. Chhattisgarh touches seven."),
    S(2, 1, "Minerals", "The Kolar Gold Fields, once India's main gold mines, are in which state?",
      ["Karnataka", "Andhra Pradesh", "Jharkhand", "Rajasthan"],
      "Kolar lies in south-eastern Karnataka. Its mines closed in 2001; Hutti, also in Karnataka, is the main working gold mine."),
    S(2, 1, "Ports", "Paradip Port, a major port on the Bay of Bengal, is in which state?",
      ["Odisha", "West Bengal", "Andhra Pradesh", "Tamil Nadu"],
      "Paradip lies near the mouth of the Mahanadi in Odisha and handles large volumes of iron ore and coal. Haldia serves West Bengal."),
    S(2, 1, "World geography", "The Andes mountain range runs along the western side of which continent?",
      ["South America", "North America", "Africa", "Australia"],
      "The Andes run about 7,000 km down the west coast of South America, the longest continental mountain range. The Rockies are in North America."),
    S(2, 2, "Constitution", "How many Schedules does the Constitution of India have today?",
      ["12", "8", "9", "10"],
      "The Constitution began with 8 Schedules. The 9th, 10th, 11th and 12th were added by later amendments, so it now has 12."),
    S(2, 1, "Economy", "An economy in which public and private sectors both play a large role, as in India, is called a:",
      ["Mixed economy", "Market economy", "Command economy", "Barter economy"],
      "India adopted a mixed economy after independence: the state runs some sectors and private firms run others. A command economy is run wholly by the state."),
    # ---------- Drill only ----------
    S(0, 1, "World geography", "Why do swimmers float so easily in the Dead Sea?",
      ["Very salty water", "Very warm water", "Strong currents", "Thin, dry air"],
      "The Dead Sea is several times saltier than the ocean. The dense, salty water pushes up harder on a body, so people float with little effort."),
    S(0, 1, "World geography", "Which is the smallest of the world's five oceans?",
      ["Arctic", "Southern", "Indian", "Atlantic"],
      "The Arctic Ocean is the smallest and shallowest. The Pacific is the largest; the Southern Ocean around Antarctica is the second smallest."),
    S(0, 2, "Ports", "Deendayal Port, earlier called Kandla, is on the coast of which state?",
      ["Gujarat", "Maharashtra", "Goa", "Kerala"],
      "Kandla, renamed Deendayal Port, lies on the Gulf of Kutch in Gujarat. It was developed after Partition when Karachi went to Pakistan."),
    S(0, 2, "Constitution", "How many Fundamental Duties does Article 51A list today?",
      ["11", "10", "12", "6"],
      "The 42nd Amendment of 1976 added ten duties. The 86th Amendment of 2002 added an eleventh: parents must give their child between 6 and 14 the chance of education."),
    S(0, 2, "Economy", "A rise in prices of hundreds of percent a year or more, out of control, is called:",
      ["Hyperinflation", "Deflation", "Disinflation", "Stagflation"],
      "Hyperinflation is extremely fast, runaway inflation. Deflation is a fall in prices, disinflation a slowdown in inflation, and stagflation high inflation with stagnant growth."),
    S(0, 2, "Economy", "Gross Domestic Product (GDP) measures the value of:",
      ["Final goods and services produced", "All goods sold and resold", "Exports minus imports", "Taxes collected by government"],
      "GDP counts the market value of final goods and services produced inside a country in a period. Counting goods every time they are resold would count the same output twice."),
    S(0, 2, "Rivers", "When the Brahmaputra enters India from Tibet, in Arunachal Pradesh, what is it called?",
      ["Siang", "Lohit", "Subansiri", "Manas"],
      "The Yarlung Tsangpo of Tibet enters Arunachal Pradesh as the Siang (or Dihang). In Assam it is joined by the Dibang and the Lohit and takes the name Brahmaputra. The Subansiri and Manas are tributaries that join it in Assam."),
    S(0, 2, "National parks", "The Great Himalayan National Park, a UNESCO World Heritage Site, is in which state?",
      ["Himachal Pradesh", "Uttarakhand", "Jammu and Kashmir", "Sikkim"],
      "The Great Himalayan National Park is in Kullu district, Himachal Pradesh. Uttarakhand has the Nanda Devi and Valley of Flowers parks."),
    S(0, 2, "Polity", "A person who is not a Member of Parliament is appointed a Union minister. Within how long must they become one, or lose the post?",
      ["Six months", "Three months", "One year", "Two years"],
      "Article 75(5) allows a minister who is not a member of either House to hold office for six consecutive months; after that they must win a seat or leave the ministry."),
    S(0, 1, "World geography", "The Strait of Gibraltar separates Spain from which country?",
      ["Morocco", "Algeria", "Portugal", "Tunisia"],
      "The Strait of Gibraltar, about 14 km wide at its narrowest, separates Spain in Europe from Morocco in Africa."),
    S(0, 2, "Climate", "The north-east monsoon brings most of its rain to which Indian state?",
      ["Tamil Nadu", "Kerala", "Gujarat", "West Bengal"],
      "From October to December the north-east (retreating) monsoon picks up moisture over the Bay of Bengal and rains on the Coromandel coast, so Tamil Nadu gets much of its yearly rain then."),
    S(0, 2, "Polity", "Which Schedule of the Constitution lists the subjects that may be given to municipalities?",
      ["Twelfth", "Eleventh", "Ninth", "Seventh"],
      "The 74th Amendment of 1992 added the Twelfth Schedule with 18 subjects for municipalities. The Eleventh Schedule, from the 73rd Amendment, lists 29 subjects for panchayats."),
]
